-- PostgreSQL: GymnasioDb. En Neon crear la base desde su consola y seleccionar SQL Editor.
-- En local Docker crea GymnasioDb y ejecuta este archivo al inicializar el volumen.
BEGIN;
CREATE TABLE "Socios" (
    "IdSocio" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" VARCHAR(100) NOT NULL,
    "Dni" VARCHAR(8) NOT NULL,
    "Telefono" VARCHAR(15) NOT NULL,
    "Email" VARCHAR(100) NOT NULL,
    CONSTRAINT "UQ_Socios_Dni" UNIQUE ("Dni"),
    CONSTRAINT "UQ_Socios_Email" UNIQUE ("Email")
);
CREATE UNIQUE INDEX "UX_Socios_Email_Normalizado" ON "Socios" (lower("Email"));
CREATE TABLE "Membresias" (
    "IdMembresia" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Plan" VARCHAR(50) NOT NULL,
    "TipoAcceso" VARCHAR(30) NOT NULL,
    "Turno" VARCHAR(50) NOT NULL,
    "DuracionMeses" INTEGER NOT NULL,
    "Precio" NUMERIC(7,2) NOT NULL,
    "IdSocio" INTEGER NOT NULL,
    CONSTRAINT "CK_Membresias_Duracion" CHECK ("DuracionMeses" BETWEEN 1 AND 36),
    CONSTRAINT "CK_Membresias_Precio" CHECK ("Precio" BETWEEN 0.01 AND 99999.99),
    CONSTRAINT "FK_Membresias_Socios" FOREIGN KEY ("IdSocio")
        REFERENCES "Socios" ("IdSocio") ON DELETE RESTRICT
);
CREATE INDEX "IX_Membresias_IdSocio" ON "Membresias" ("IdSocio");
INSERT INTO "Socios" ("Nombre", "Dni", "Telefono", "Email") VALUES
('Diego Ramirez', '71234567', '987654321', 'diego.ramirez@gym.example'),
('Valeria Lopez', '87654321', '912345678', 'valeria.lopez@gym.example');
INSERT INTO "Membresias" ("Plan", "TipoAcceso", "Turno", "DuracionMeses", "Precio", "IdSocio") VALUES
('Mensual', 'Musculacion', 'Mañana', 1, 120.00, 1),
('Trimestral Premium', 'Completo', 'Libre', 3, 320.00, 1),
('Anual', 'Completo', 'Tarde', 12, 1100.00, 2);
COMMIT;
